function errorText(code){const errors={invalid_credentials:['اسم المستخدم أو كلمة المرور غير صحيحة.','Invalid username or password.'],mfa_required_or_invalid:['رمز MFA مطلوب أو غير صحيح.','An MFA code is required or invalid.'],invalid_mfa_code:['رمز MFA غير صحيح أو خارج نافذة الوقت.','The MFA code is invalid or outside the time window.'],recent_mfa_required:['تحقق من MFA الآن ثم أعد الإجراء خلال خمس دقائق.','Verify MFA now, then retry within five minutes.'],invalid_setup_token:['رمز التهيئة غير صحيح. اقرأ ملف data/setup-token على هذا الجهاز.','Invalid setup token. Read the local data/setup-token file.'],password_requires_14_to_256_characters:['كلمة المرور يجب أن تكون بين 14 و256 حرفًا.','Use a password of 14–256 characters.'],insufficient_role:['دورك لا يسمح بهذا الإجراء.','Your role does not allow this action.'],too_many_attempts:['محاولات كثيرة. انتظر 15 دقيقة.','Too many attempts. Wait 15 minutes.'],preflight_state_changed:['تغيّرت بيانات الأصل. أنشئ معاينة جديدة قبل التنفيذ.','Asset state changed. Create a new preview.'],approval_expired:['انتهت صلاحية الموافقة. أنشئ طلبًا جديدًا.','Approval expired. Create a new request.'],independent_approver_required:['الموافقة تحتاج مسؤولًا آخر غير مقدم الطلب.','A different administrator must approve.'],invalid_json:['ملف JSON غير صالح.','Invalid JSON file.'],event_id_content_conflict:['معرّف الحدث موجود بمحتوى مختلف. لم يُحفظ الاستيراد.','An event ID already exists with different content. Import was rolled back.'],source_name_exists:['اسم المصدر موجود. اختر اسمًا مختلفًا.','Source name already exists.'],username_exists:['اسم المستخدم موجود.','Username already exists.']};return errors[code]?tr(...errors[code]):tr(`تعذر إكمال العملية: ${code}`,`The operation could not be completed: ${code}`);}
async function api(url,data,method){const response=await fetch(url,{method:method||(data?'POST':'GET'),credentials:'same-origin',headers:{Accept:'application/json',...(data?{'Content-Type':'application/json','X-CSRF-Token':state.csrf||''}:{})},body:data?JSON.stringify(data):undefined});const result=await response.json();if(!response.ok){if(response.status===401&&state.user){state.user=null;state.csrf=null;await authPage(false);}throw new Error(errorText(result.error));}return result;}
let toastTimer;
function toast(message,error=false){const node=document.querySelector('#toast');node.textContent=message;node.hidden=false;node.setAttribute('role',error?'alert':'status');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,5500);}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function modal(name,body){document.querySelector('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${h(name)}</h2>${button('close',icon('close'),'','icon-button',`aria-label="${tr('إغلاق','Close')}"`)}</div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
dialog.addEventListener('close',()=>{document.querySelector('#dialog-content').replaceChildren();});
function empty(name,description,action){return `<div class="empty"><span class="empty-icon">${icon(name)}</span><strong>${h(description[0])}</strong><p>${h(description[1])}</p>${action||''}</div>`;}
function header(subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">SECURITY OPERATIONS / CG AI</div><h1>${h(title(state.view))}</h1><p>${h(subtitle)}</p></div><div class="heading-actions">${actions}${button('refresh',icon('refresh'),'','icon-button',`aria-label="${tr('تحديث','Refresh')}"`)}</div></div>`;}
