function agentInventoryPanel(d){const aLabel=value=>{const values={windows:['Windows','Windows'],linux:['Linux','Linux'],macos:['macOS','macOS'],'windows-security':['سجل الأمان','Security log'],'windows-system':['سجل النظام','System log'],'windows-application':['سجل التطبيقات','Application log'],sysmon:['Sysmon','Sysmon'],'linux-auditd':['auditd','auditd'],'linux-journald':['journald','journald'],'linux-syslog':['syslog','syslog'],'macos-unified-log':['Unified Log','Unified Log'],collected:['مجمّع','Collected'],'access-denied':['لا توجد صلاحية','Access denied'],'not-installed':['غير مثبت','Not installed'],disabled:['معطل','Disabled'],on:['يعمل','On'],off:['متوقف','Off'],snoozed:['مؤجل','Snoozed'],av:['مضاد فيروسات','Antivirus'],edr:['EDR','EDR'],firewall:['جدار ناري','Firewall'],healthy:['سليم','Healthy'],gaps:['فجوات','Gaps'],stale:['متأخر عن الإبلاغ','Stale'],reporting:['يبلغ','Reporting'],'no-active-av-edr':['لا توجد حماية AV/EDR تعمل','No active AV/EDR'],'signatures-older-than-7-days':['التواقيع أقدم من 7 أيام','Signatures older than 7 days'],'realtime-protection-off':['الحماية اللحظية متوقفة','Real-time protection off'],'firewall-profile-off':['ملف جدار ناري متوقف','Firewall profile off']};const v=String(value);if(values[v])return tr(...values[v]);const m=v.match(/^(.*)-(access-denied|not-installed|disabled)$/);if(m)return `${aLabel(m[1])}: ${aLabel(m[2])}`;if(v.startsWith('protection-'))return `${tr('حماية','Protection')} ${aLabel(v.slice(11).split(':')[0])}: ${h(v.split(':').slice(1).join(':'))}`;return identitySignalLabel(v);};return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('وكلاء الأجهزة المُدارة الاختيارية','Optional managed-device agents')} · CG-010</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar||d.claim,d.claim))}</div>${table([tr('الجهاز والوكيل','Device / agent'),tr('قنوات السجلات','Log channels'),tr('الخدمات والعمليات','Services / processes'),tr('حالة الحماية','Protection status'),tr('الحالة والفجوات','State / gaps')],d.items.map(item=>[`${button('asset',h(item.asset.hostname||item.asset.external_id),item.asset.id,'text-button')}<div class="secondary">${h(aLabel(item.platform))} · v${h(item.agent_version)} · ${tr('اختياري','Opt-in')}</div><div class="secondary mono">${h(item.agent_id)}</div>`,item.channels.map(channel=>`${h(aLabel(channel.channel))} · ${h(aLabel(channel.status))}${channel.events_last_hour!==null?` · ${channel.events_last_hour}/${tr('ساعة','h')}`:''}<div class="secondary">${h(channel.reason||'')}</div>`).join(''),`${tr('خدمات','Services')}: ${item.services.running}/${item.services.total}<div class="secondary">${tr('تلقائية متوقفة','Auto-start stopped')}: ${item.auto_start_stopped}</div>${tr('عمليات','Processes')}: ${item.processes.total}<div class="secondary">${tr('أسطر الأوامر','Command lines')}: ${item.command_lines_collected?tr('تُجمع','Collected'):tr('لا تُجمع','Not collected')}</div>`,item.protection.map(p=>`${h(p.name)} · ${h(aLabel(p.state))}<div class="secondary">${h(aLabel(p.type))}${p.signatures_age_days!==null?` · ${tr('عمر التواقيع','Signature age')}: ${p.signatures_age_days} ${tr('يوم','days')}`:''}${p.realtime!==null?` · ${tr('لحظية','Real-time')}: ${p.realtime?tr('نعم','Yes'):tr('لا','No')}`:''}</div>`).join('')||tr('لا منتجات حماية','No protection products'),`${h(aLabel(item.agent_state))}<div class="secondary">${h(aLabel(item.reporting_state))} · ${item.report_age_minutes} ${tr('دقيقة','min')} · ${tr('القنوات','Channels')} ${item.channel_coverage.collected}/${item.channel_coverage.total}<br>${item.gaps.map(aLabel).join('<br>')||tr('لا فجوات','No gaps')}</div>${button('event',tr('دليل الوكيل','Agent evidence'),item.event_id,'text-button')}`]),tr('لا توجد تقارير وكلاء','No agent reports'),d)}</div></section>`;}
