function sensitiveChangesPanel(d){const sLabel=value=>{const values={registry:['السجل Registry','Registry'],file:['ملف','File'],service:['خدمة','Service'],software:['برنامج','Software'],firewall:['جدار ناري','Firewall'],account:['حساب','Account'],policy:['سياسة','Policy'],added:['إضافة','Added'],removed:['حذف','Removed'],modified:['تعديل','Modified'],'snapshot-diff':['مقارنة لقطات','Snapshot diff'],'event-log':['سجل الأحداث','Event log'],'needs-review':['يحتاج مراجعة','Needs review'],authorized:['مصرح','Authorized'],informational:['للعلم','Informational'],'persistence-location':['موقع استمرارية','Persistence location'],'privileged-group':['مجموعة مميزة','Privileged group'],'hosts-file':['ملف hosts','Hosts file'],'inbound-allow-rule':['قاعدة سماح واردة','Inbound allow rule']};return values[value]?tr(...values[value]):identitySignalLabel(value);};const counts=Object.entries(d.by_category||{}).map(([k,v])=>`${h(sLabel(k))}: ${v}`).join(' · ');return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('مراقبة التغييرات الحساسة','Sensitive change monitoring')} · CG-011</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar||d.claim,d.claim))}</div><div class="secondary">${counts||'—'} · ${tr('تحتاج مراجعة','Needs review')}: ${d.needs_review||0}</div>${table([tr('الجهاز والفئة','Host / category'),tr('العنصر','Object'),tr('قبل → بعد','Before → after'),tr('الكشف','Detection'),tr('المخاطر والمراجعة','Risk / review')],d.items.map(item=>[`${button('asset',h(item.asset.hostname||item.asset.external_id),item.asset.id,'text-button')}<div class="secondary">${h(sLabel(item.category))} · ${h(sLabel(item.action))}</div>`,`<span class="mono">${h(item.object_ref)}</span>`,`<div class="secondary mono">${h(item.before_summary||'—')}</div>→<div class="secondary mono">${h(item.after_summary||'—')}</div>`,`${h(sLabel(item.detector))}<div class="secondary">${h(date(item.detected_at))}${item.baseline_at?` · ${tr('خط الأساس','Baseline')}: ${h(date(item.baseline_at))}`:''}<br>${h(item.actor_ref||tr('الفاعل غير معروف','Actor unknown'))}</div>`,`${h(identitySignalLabel(item.risk))} · ${h(sLabel(item.review_state))}<div class="secondary">${item.risk_reasons.map(sLabel).join(tr('، ',', '))||'—'}<br>${h(item.authorization_ref||tr('بلا مرجع تفويض','No authorization reference'))}</div>${button('event',tr('دليل التغيير','Change evidence'),item.event_id,'text-button')}`]),tr('لا توجد تغييرات حساسة مسجلة','No sensitive changes recorded'),d)}</div></section>`;}
