function detectionRulesPanel(d){const kindLabel=value=>({'endpoint.process_causality':tr('سببية العمليات','Process causality'),'endpoint.defense_tamper':tr('التلاعب بالحماية','Defense tamper'),'endpoint.ransomware_posture':tr('وضع الفدية','Ransomware posture'),'agent.inventory_report':tr('تقرير الوكيل','Agent report')})[value]||value;return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('قواعد كشف الخبيث والفدية والتلاعب','Malware, ransomware and tamper detection rules')} · CG-012</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar||d.claim,d.claim))}</div>${table([tr('القاعدة والإصدار','Rule / version'),tr('ما تكشفه','What it detects'),tr('مصدر الدليل','Evidence source'),tr('الخطورة','Severity'),tr('التنبيهات','Alerts')],d.rules.map(rule=>[`<span class="mono">${h(rule.id)}</span><div class="secondary">v${h(rule.version)}</div>`,`${h(tr(rule.title_ar,rule.title_en))}<div class="secondary">${h(tr(rule.description_ar||rule.description,rule.description))}</div>`,h(kindLabel(rule.evidence_kind)),pill(rule.severity),`${tr('مفتوحة','Open')}: ${rule.alerts_open} · ${tr('الكل','Total')}: ${rule.alerts_total}<div class="secondary">${rule.last_alert_at?h(date(rule.last_alert_at)):'—'}</div>`]),tr('لا توجد قواعد','No rules'),{total:d.rules.length,limit:d.rules.length||1,offset:0})}</div></section>`;}
const threatsEvidenceView=threatsView;
