function softwareVulnerabilityPanel(d){const vLabel=value=>({vulnerable:tr('متأثر','Vulnerable'),'fixed-by-update':tr('مصلح بتحديث','Fixed by update'),'version-unknown':tr('الإصدار غير معروف','Version unknown')})[value]||value;return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('جرد البرامج والتحديثات والثغرات','Software, update and vulnerability inventory')} · CG-013</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar||d.claim,d.claim))}</div><div class="secondary">${tr('كتالوجات الثغرات','Vulnerability catalogs')}: ${d.catalogs.map(c=>`${h(c.catalog_id)} (${c.entries}) · ${h(c.source)}`).join(' · ')||tr('لم يُستورد كتالوج بعد','No catalog imported yet')}</div>${table([tr('الجهاز ونظام التشغيل','Device / OS'),tr('البرامج والتحديثات','Software / updates'),tr('الثغرات المرتبطة بالإصدار','Version-linked vulnerabilities'),tr('الملخص','Summary')],d.items.map(item=>[`${button('asset',h(item.asset.hostname||item.asset.external_id),item.asset.id,'text-button')}<div class="secondary">${h(item.os.name)} · ${h(item.os.version)}${item.os.build?` (${h(item.os.build)})`:''}</div>`,`${tr('برامج','Programs')}: ${item.software_count} · ${tr('تحديثات','Updates')}: ${item.update_count}<div class="secondary">${item.software.slice(0,8).map(app=>`${h(app.name)} ${h(app.version||'—')}`).join('<br>')}${item.software_count>8?`<br>+${item.software_count-8}`:''}</div>`,item.matches.slice(0,15).map(match=>`<span class="mono">${h(match.vuln_id)}</span> · ${h(vLabel(match.status))}${match.kev?' · KEV':''}<div class="secondary">${h(match.product)} ${h(match.installed_version||'—')} → ${h(match.fixed_version||match.fixing_update||'—')} · CVSS ${match.cvss??'—'}</div>`).join('')||tr('لا تطابق في الكتالوجات المستوردة','No match in imported catalogs'),`${tr('متأثر','Vulnerable')}: ${item.vulnerable_count} · KEV: ${item.kev_count}<div class="secondary">${tr('أعلى CVSS','Max CVSS')}: ${item.max_cvss||'—'} · ${tr('إصدارات غير معروفة','Unknown versions')}: ${item.unknown_versions}</div>${button('event',tr('دليل الجرد','Inventory evidence'),item.event_id,'text-button')}`]),tr('لا يوجد جرد برامج','No software inventory'),d)}</div></section>`;}
function vulnerabilityAssessmentPanel(d){const badge=(color,text)=>`<span class="pill ${color}">${h(text)}</span>`;
  const feedName=value=>({'cisa-kev':'CISA KEV','first-epss':'FIRST EPSS','nvd-cve':'NVD CVE / CVSS'})[value]||value,feedState=f=>f.state==='current'?badge('success',tr('محدث','Current')):f.state==='stale'?badge('warning',tr('قديم','Stale')):badge('warning',tr('غير مستورد','Not imported'));
  const stateBadge=value=>({active:badge('success',tr('نشط','Active')),scheduled:badge('info',tr('مجدول','Scheduled')),expired:badge('warning',tr('انتهت النافذة','Window ended')),closed:badge('info',tr('مغلق','Closed'))})[value]||h(value);
  const levelText=value=>({'internet-exposed':tr('مكشوف للإنترنت','Internet-exposed'),'network-reachable':tr('قابل للوصول عبر الشبكة','Network-reachable'),'no-inbound-evidence':tr('لا دليل على وصول وارد','No inbound evidence'),unknown:tr('لا توجد بيانات انكشاف','No exposure data'),'not-assessed':tr('لم يُقيَّم','Not assessed')})[value]||value;
  const levelBadge=value=>badge(value==='internet-exposed'?'danger':value==='network-reachable'?'warning':'info',levelText(value));
  const vectorText=value=>({network:tr('شبكي','Network'),adjacent:tr('شبكة مجاورة','Adjacent'),local:tr('محلي','Local'),physical:tr('فيزيائي','Physical')})[value]||tr('غير معروف','Unknown');
  const pct=value=>`${(value*100).toFixed(value<0.01?2:1)}%`;
  const feeds=`<h3>${tr('مصادر الاستخبارات','Intelligence feeds')}</h3>${table([tr('المصدر','Feed'),tr('الحالة','State'),tr('تاريخ النشر','Published'),tr('الإدخالات','Entries')],d.feeds.map(f=>[h(feedName(f.feed)),feedState(f),f.published_at?`${h(date(f.published_at))}<div class="secondary">${f.age_days} ${tr('يوم','days')} · ${tr('الحد','limit')} ${f.max_age_days} · ${h(f.feed_version||'')}</div>`:'—',String(f.entries)]),'',{total:d.feeds.length,limit:d.feeds.length,offset:0})}`;
  const blocks=d.items.map(a=>`<div class="divider"></div><h3>${h(a.assessment_id)} ${stateBadge(a.state)}</h3><div class="secondary">${tr('مرجع التفويض','Authorization')}: ${h(a.authorization_ref)} · ${tr('اعتمده','approved by')} ${h(a.approved_by)} · ${tr('النافذة','window')} ${h(date(a.window_start))} → ${h(date(a.window_end))}<br>${tr('النطاق','Scope')}: ${h([...a.targets.asset_refs,...a.targets.networks].join(', '))} · ${tr('الأساليب','methods')}: ${h(a.methods.map(m=>({'inventory-version-match':tr('مطابقة الإصدارات المثبتة','installed version matching'),'passive-exposure-evidence':tr('دليل انكشاف سلبي','passive exposure evidence')})[m]||m).join(tr('، ',', ')))}<br>${tr('أصول ضمن النطاق','Assets in scope')} ${a.target_assets} · ${tr('قُيّمت ضمن النافذة','assessed in window')} ${a.assessed_assets} · ${tr('نتائج','findings')} ${a.findings_total} · CISA KEV ${a.summary.kev} · EPSS ≥10% ${a.summary.epss_over_10_percent} · ${tr('قابل للوصول عن بعد دون تفاعل','remotely reachable without interaction')} ${a.summary.network_vector_on_reachable_asset} · ${tr('يتطلب تفاعل المستخدم','needs user interaction')} ${a.summary.needs_user_interaction} · ${tr('بلا استخبارات','without intelligence')} ${a.summary.without_intel}</div>
    ${table([tr('الأصل','Asset'),tr('الثغرة','Vulnerability'),tr('دليل الاستغلال','Exploitation evidence'),tr('CVSS ومتجه الهجوم','CVSS / Attack vector'),tr('الانكشاف','Exposure')],a.findings.map(f=>[button('asset',h(f.asset.hostname||f.asset.external_id),f.asset.id,'text-button'),`<strong>${h(f.vuln_id)}</strong><div class="secondary">${h(f.product)} ${h(f.installed_version||tr('إصدار غير معروف','version unknown'))}${f.fixed_version?` → ${h(f.fixed_version)}`:''}${f.cwe.length?` · ${h(f.cwe.join(', '))}`:''}</div>`,
      `${f.kev?badge('danger','CISA KEV'):''}${f.kev_detail?`<div class="secondary">${tr('أضيفت','added')} ${h(day(f.kev_detail.date_added))}${f.kev_detail.due_date?` · ${tr('موعد المعالجة','due')} ${h(day(f.kev_detail.due_date))}`:''}${f.kev_detail.known_ransomware?` · ${tr('استُخدمت في فدية','used by ransomware')}`:''}</div>`:f.kev?`<div class="secondary">${tr('من الكتالوج','from catalog')}</div>`:''}${f.epss?`<div>EPSS ${pct(f.epss.score)} <span class="secondary">(${tr('المئين','percentile')} ${pct(f.epss.percentile??0)})</span></div>`:`<div class="secondary">EPSS —</div>`}`,
      `${f.cvss!=null?h(String(f.cvss)):'—'} <span class="secondary">${h(f.cvss_source||'')}</span><div class="secondary">${tr('متجه الهجوم','Attack vector')}: ${h(vectorText(f.attack_vector))}${f.user_interaction==='required'?` · ${tr('يتطلب تفاعل المستخدم','needs user interaction')}`:f.user_interaction==='none'?` · ${tr('بلا تفاعل مستخدم','no user interaction')}`:''}</div>`,
      `${levelBadge(f.exposure.level)}${f.exposure_relevant?` ${badge('danger',tr('قابل للاستغلال عن بعد','Remotely reachable'))}`:''}<div class="secondary">${(f.exposure.listening_services||[]).slice(0,4).map(h).join(', ')}${(f.exposure.firewall_inbound_from_any||[]).slice(0,3).map(r=>`<br>${tr('قاعدة تسمح من أي مصدر','allow from any')}: ${h(r.rule)} ${h(r.protocol)}/${h(r.ports.join(','))}`).join('')}</div>`]),tr('لا نتائج ضمن هذا التقييم','No findings in this assessment'),{total:a.findings_total,limit:a.findings.length,offset:0})}
    ${a.not_assessed_in_window.length?`<div class="secondary">${tr('لم يُقيَّم ضمن النافذة (جرد خارج وقت التفويض)','Not assessed in window (inventory outside the authorized time)')}: ${a.not_assessed_in_window.map(x=>h(x.asset.hostname||x.asset.external_id)).join(', ')}</div>`:''}`).join('');
  const outside=d.outside_authorized_scope.length?`<div class="divider"></div><h3>${tr('خارج النطاق المصرح به','Outside authorized scope')}</h3><div class="hint">${tr('أجهزة لديها جرد برامج لكنها ليست ضمن أي نطاق تقييم معتمد ونافذته؛ لا تُقيَّم.','Devices with a software inventory that are not in any approved assessment scope and window; they are not assessed.')}</div><div class="secondary">${d.outside_authorized_scope.map(x=>h(x.asset.hostname||x.asset.external_id)).join(', ')}</div>`:'';
  return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('تقييم الثغرات ضمن نطاق مصرح به','Authorized vulnerability assessment')} · CG-024</h2></div><div class="panel-body"><div class="hint">${tr('يجري تقييم الثغرات فقط ضمن نطاق معلن ومعتمد (أصول أو شبكات، نافذة زمنية، مرجع تفويض، ومعتمِد). تأتي النتائج من مطابقة الإصدارات المثبتة مع كتالوجات مستوردة (نطاقات CVE من بيانات NVD CPE)، وتُثرى بدرجة CVSS ومتجه الهجوم من NVD واحتمال الاستغلال من FIRST EPSS وإدراج CISA KEV، مع دليل الانكشاف من بيانات الاكتشاف والخدمات البعيدة والجدار الناري المجمعة مسبقًا. تُعد الثغرة قابلة للوصول عن بعد فقط إذا كان متجهها شبكيًا ولا تتطلب تفاعل المستخدم والأصل يقبل اتصالات واردة؛ أما ثغرات فتح المحتوى (المتصفح والقارئ) فتظهر منفصلة. الجرد المرصود خارج النافذة أو خارج النطاق لا يُقيَّم. لا يُفحص أي شيء ولا يُستغل، والترتيب حسب KEV وEPSS وCVSS ليس درجة مخاطر.',d.claim)}</div>${feeds}${blocks||`<div class="secondary">${tr('لا يوجد نطاق تقييم معتمد بعد.','No approved assessment scope yet.')}</div>`}${outside}</div></section>`;}
function vulnerabilityRiskPanel(d){const badge=(color,text)=>`<span class="pill ${color}">${h(text)}</span>`;
  const bandText=value=>({critical:tr('حرج','Critical'),high:tr('مرتفع','High'),medium:tr('متوسط','Medium'),low:tr('منخفض','Low')})[value]||value,bandBadge=value=>badge(value==='critical'||value==='high'?'danger':value==='medium'?'warning':'info',bandText(value));
  const factorText=value=>({exploitation:tr('إثبات الاستغلال','Exploitation'),exposure:tr('الانكشاف','Exposure'),asset_importance:tr('أهمية الأصل','Asset importance'),severity:tr('الشدة التقنية','Severity'),control:tr('ضابط قائم','Existing control')})[value]||value;
  const missingText=value=>({'no-exploitation-intelligence':tr('لا يوجد KEV أو EPSS','no KEV or EPSS'),'exposure-or-vector-unknown':tr('الانكشاف أو المتجه غير معروف','exposure or vector unknown'),'asset-context-missing':tr('لا يوجد سياق أهمية للأصل','no asset importance context'),'cvss-missing':tr('لا توجد درجة CVSS','no CVSS score')})[value]||value;
  const modelLabel=k=>k==='bands'?tr('الفئات','Bands'):k==='controls'?tr('الضوابط القائمة','Existing controls'):factorText(k);
  const model=Object.entries(d.model).map(([k,v])=>`<li><strong>${h(modelLabel(k))}</strong>: ${h(v)}</li>`).join('');
  return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('ترتيب مخاطر الثغرات','Vulnerability risk ranking')} · CG-025</h2></div><div class="panel-body"><div class="hint">${tr('تُجمع درجة كل ثغرة من إثبات الاستغلال (CISA KEV وEPSS) والانكشاف (متجه الهجوم وتفاعل المستخدم وقابلية الوصول) وأهمية الأصل (أهمية الخدمة وحساسية البيانات) وشدة CVSS، وتُخصم الضوابط القائمة فقط إذا سُجّلت بدليل. كل نقطة تظهر مع دليلها وتُعلَّم المدخلات الناقصة، فالترتيب قابل للتفسير وليس CVSS وحده. هو لترتيب العمل ولا يثبت قابلية الاستغلال.',d.claim)}</div>
    <div class="secondary">${['critical','high','medium','low'].map(b=>`${bandBadge(b)} ${d.by_band[b]}`).join(' ')} · ${tr('تغيّر ترتيبها عن ترتيب CVSS وحده','reordered compared with CVSS alone')}: ${d.reordered_vs_cvss}</div>
    <details><summary>${tr('كيف تُحسب الدرجة','How the score is built')}</summary><ul>${model}</ul></details>
    ${table([tr('الترتيب','Rank'),tr('الأصل','Asset'),tr('الثغرة','Vulnerability'),tr('الدرجة','Score'),tr('لماذا','Why'),tr('مدخلات ناقصة','Missing inputs')],d.items.map(x=>[`<strong>#${x.rank}</strong><div class="secondary">${tr('ترتيب CVSS وحده','CVSS-only rank')} #${x.cvss_only_rank}</div>`,button('asset',h(x.asset.hostname||x.asset.external_id),x.asset.id,'text-button'),`<strong>${h(x.vuln_id)}</strong><div class="secondary">${h(x.product)} ${h(x.installed_version||'')}${x.fixed_version?` → ${h(x.fixed_version)}`:''}${x.kev_past_due?` · ${tr('تجاوز موعد CISA','past CISA due date')}`:''}</div>`,`<strong>${x.score}</strong>/100 ${bandBadge(x.risk_band)}`,`<ul class="factor-list">${x.factors.map(f=>`<li>${f.points>0?'+':''}${f.points} ${h(factorText(f.factor))}: <span class="secondary">${h(tr(f.evidence_ar||f.evidence,f.evidence))}</span></li>`).join('')}</ul>`,x.uncertain.length?x.uncertain.map(u=>h(missingText(u))).join('<br>'):'—']),tr('لا توجد نتائج في تقييم نشط','No findings in an active assessment'),{total:d.total,limit:d.items.length,offset:0})}</div></section>`;}
function validationProgramPanel(d){const badge=(color,text)=>`<span class="pill ${color}">${h(text)}</span>`;
  const tierText=value=>({passive:tr('سلبي','Passive'),'low-impact-validation':tr('تحقق منخفض الأثر بتفويض','Low-impact authorized validation'),'adversary-emulation':tr('محاكاة الخصم (مختبر فقط)','Adversary emulation (lab only)')})[value]||value;
  const tierDesc=value=>({passive:tr('تحليل أدلة مجمعة فقط؛ لا يصل أي طلب أو أمر إلى الأهداف.','Analysis of collected evidence only; nothing reaches the targets.'),'low-impact-validation':tr('فحوص للقراءة فقط أو بطلب واحد من قائمة مسموحة، بتفويض ومعتمِد ونافذة حتى 14 يومًا وحد معدل حتى 60 في الدقيقة وشروط إيقاف؛ بلا استغلال أو كتابة.','Allow-listed read-only or single-request checks with authorization, approver, a window up to 14 days, at most 60 per minute and stop conditions; no exploitation or writes.'),'adversary-emulation':tr('تقنيات MITRE ATT&CK في بيئة مختبر معزولة فقط، بموافقة شخصين مختلفين ودليل عزل وخطة تراجع.','MITRE ATT&CK techniques only in an isolated lab, approved by two different people, with isolation evidence and a rollback plan.')})[value]||'';
  const outcomeText=value=>({pass:tr('نجح','pass'),fail:tr('فشل','fail'),blocked:tr('مُنع','blocked'),error:tr('خطأ','error'),'not-run':tr('لم يُنفذ','not run')})[value]||value,envText=value=>({production:tr('إنتاج','production'),staging:tr('تجهيز','staging'),lab:tr('مختبر','lab')})[value]||value;
  const stateText=value=>({open:tr('النافذة مفتوحة','Window open'),scheduled:tr('مجدولة','Scheduled'),ended:tr('انتهت النافذة','Window ended'),cancelled:tr('ملغاة','Cancelled')})[value]||value;
  const statusText=value=>({approved:tr('معتمدة','Approved'),draft:tr('مسودة','Draft'),cancelled:tr('ملغاة','Cancelled')})[value]||value;
  const reasonText=value=>{const [k,v]=value.split(/:(.*)/);return ({'no-such-plan':tr('لا توجد خطة بهذا المعرّف','no such plan'),'outside-plan-window':tr('خارج نافذة الخطة','outside the plan window'),'technique-not-in-plan':tr('تقنية غير واردة في الخطة','technique not in plan'),'target-not-in-plan':tr('هدف خارج الخطة','target not in plan'),'plan-draft':tr('الخطة مسودة غير معتمدة','plan is a draft'),'plan-cancelled':tr('الخطة ملغاة','plan cancelled')})[k]+(v?` (${v})`:'');};
  const outcomes=o=>`${tr('نجح','pass')} ${o.pass} · ${tr('فشل','fail')} ${o.fail} · ${tr('مُنع','blocked')} ${o.blocked} · ${tr('خطأ','error')} ${o.error} · ${tr('لم يُنفذ','not run')} ${o['not-run']}`;
  const runRow=r=>`<li>${r.compliance==='within-plan'?badge('success',tr('ضمن الخطة','Within plan')):badge('danger',tr('خارج الخطة','Out of plan'))} <strong>${h(r.run_id)}</strong> · ${h(date(r.started_at))} · ${h(r.executed_by)} · ${outcomes(r.outcomes)}${r.reasons.length?`<div class="secondary">${r.reasons.map(x=>h(reasonText(x))).join(tr('، ',', '))}</div>`:''}<ul class="factor-list">${r.results.slice(0,12).map(x=>`<li>${h(outcomeText(x.outcome))} · ${h(x.technique_id)} → ${h(x.target_ref)}${x.observation?` <span class="secondary">${h(x.observation)}</span>`:''}</li>`).join('')}</ul></li>`;
  const tiersRow=`<ul class="factor-list">${['passive','low-impact-validation','adversary-emulation'].map(k=>`<li><strong>${h(tierText(k))}</strong> (${d.by_tier[k]}): <span class="secondary">${h(tierDesc(k))}</span></li>`).join('')}</ul>`;
  return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('طبقات اختبار التحقق','Validation tiers')} · CG-026</h2></div><div class="panel-body"><div class="hint">${tr('ثلاث طبقات بقواعد مفروضة: تُرفض الخطة التي تخالف قواعد طبقتها، ويُقارن كل تشغيل بخطته المعتمدة فيُعلَّم ويُنبَّه عن أي تقنية أو هدف أو وقت خارجها، ولا تُحسب نتائجه دليلًا للخطة. CyberGuard يحكم الاختبارات ويسجلها ولا ينفذ هجمات.',d.claim)}</div>${tiersRow}
    <div class="secondary">${tr('تشغيلات خارج خطتها','Runs outside their plan')}: ${d.out_of_plan_runs}</div>
    ${table([tr('الخطة','Plan'),tr('الطبقة والبيئة','Tier / environment'),tr('التفويض والنافذة','Authorization / window'),tr('التشغيلات والنتائج','Runs / results')],d.items.map(p=>[`<strong>${h(p.plan_id)}</strong> ${badge(p.status==='approved'?'success':'warning',statusText(p.status))}<div class="secondary">${h(p.title)}</div>`,`${h(tierText(p.tier))}<div class="secondary">${h(envText(p.environment))} · ${p.techniques.map(t=>h(t.id)).join(', ')}</div>`,`${h(p.authorization_ref||'—')} · ${h(p.approved_by||'—')}${p.second_approver?` + ${h(p.second_approver)}`:''}<div class="secondary">${h(stateText(p.window_state))}: ${h(date(p.window_start))} → ${h(date(p.window_end))}${p.safeguards.rate_limit_per_minute?` · ${p.safeguards.rate_limit_per_minute}/${tr('دقيقة','min')}`:''}</div>`,`${outcomes(p.results)}${p.runs.length?`<ul class="factor-list">${p.runs.map(runRow).join('')}</ul>`:`<div class="secondary">${tr('لا تشغيلات بعد','No runs yet')}</div>`}`]),tr('لا توجد خطط اختبار','No validation plans'),{total:d.total,limit:d.items.length,offset:0})}
    ${d.orphan_runs.length?`<h3>${tr('تشغيلات بلا خطة','Runs without a plan')}</h3><ul class="factor-list">${d.orphan_runs.map(runRow).join('')}</ul>`:''}</div></section>`;}
function detectionCoveragePanel(d){const badge=(color,text)=>`<span class="pill ${color}">${h(text)}</span>`;
  const detText=value=>({detected:tr('اكتُشف','Detected'),'telemetry-only':tr('وصلت بيانات دون تنبيه','Telemetry only'),'no-telemetry':tr('لا بيانات من الهدف','No telemetry')})[value]||value;
  const gapBadge=x=>x.settling?badge('info',tr('قيد التسوية','Settling')):x.gap==='rule-gap'?badge('warning',tr('فجوة قاعدة','Rule gap')):x.gap==='visibility-gap'?badge('danger',tr('فجوة رؤية','Visibility gap')):x.detection==='detected'?badge('success',tr('اكتُشف','Detected')):'—';
  const expText=value=>({alert:tr('تنبيه','alert'),log:tr('سجل','log'),none:tr('لا يُتوقع','none')})[value]||value;
  const s=d.summary;
  return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('قياس الكشف وفجوات الكشف','Detection measurement and gaps')} · CG-027</h2></div><div class="panel-body"><div class="hint">${tr('يُقاس الكشف ولا يُفترض: لكل تقنية نُفذت ضمن خطة معتمدة يُفحص هل صدر تنبيه على الهدف من أدلة رُصدت أثناء التشغيل (من دقيقة قبل البدء حتى 15 دقيقة بعد الانتهاء). التقنية المتوقع لها تنبيه ولم تُكتشف تصبح فجوة: فجوة رؤية إذا لم تصل بيانات من الهدف، وفجوة قاعدة إذا وصلت البيانات ولم تعمل أي قاعدة. نجاح الفحص أو منع التقنية نتيجة اختبار وليس دليلًا على أن الثغرة قابلة للاستغلال أو مكتشفة.',d.claim)}</div>
    <div class="secondary">${tr('نسبة الكشف','Detection rate')}: <strong>${s.detection_rate===null?'—':s.detection_rate+'%'}</strong> (${s.detected}/${s.expected_alert}) · ${tr('فجوات قاعدة','rule gaps')} ${s.rule_gaps} · ${tr('فجوات رؤية','visibility gaps')} ${s.visibility_gaps} · ${tr('قيد التسوية','settling')} ${s.settling}</div>
    ${table([tr('التقنية','Technique'),tr('الهدف','Target'),tr('المتوقع','Expected'),tr('ما رُصد','Observed'),tr('النتيجة','Result')],d.items.map(x=>[`<strong>${h(x.technique_id)}</strong><div class="secondary">${h(x.technique_name||'')} · ${h(x.plan_id)} / ${h(x.run_id)}</div>`,`${x.asset?button('asset',h(x.asset.hostname||x.asset.external_id),x.asset.id,'text-button'):h(x.target_ref)}${x.target_reporting?'':`<div class="secondary">${tr('لم يرسل الهدف أي بيانات','target has never reported')}</div>`}`,h(expText(x.expected_detection)),`${h(detText(x.detection))}<div class="secondary">${x.alerts.map(a=>h(a.rule_id)).join(', ')||`${x.telemetry_events} ${tr('حدث','events')}`}</div>`,gapBadge(x)]),tr('لا توجد تقنيات منفذة ضمن خطة معتمدة','No executed techniques in an approved plan'),{total:d.total,limit:d.items.length,offset:0})}</div></section>`;}
function criticalProductionPanel(d){const p=d.policy;return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('حماية الأصول الحرجة في الإنتاج','Critical production asset protection')} · CG-028</h2></div><div class="panel-body"><div class="hint">${tr('تُفرض أرضية أمان من المنصة ولا يستطيع المسؤول تجاوزها: لا محاكاة خصم في الإنتاج، والتحقق منخفض الأثر يستهدف الأصل صراحة بلا نطاق شبكة، وبحد أقصى ستة فحوص في الدقيقة وخمسة أصول حرجة في الخطة. تعتمد الحماية على آخر دليل مسجل لحرجية الأصل؛ الأصل غير المصنف لا يُفترض أنه محمي.',d.claim)}</div><div class="secondary">${tr('تجاوز المسؤول','Administrator bypass')}: <strong>${p.role_bypass?tr('مسموح','Allowed'):tr('ممنوع','Blocked')}</strong> · ${tr('حد المعدل','Rate limit')} ${p.max_rate_per_minute}/${tr('دقيقة','min')} · ${tr('نطاقات الشبكة الواسعة','Broad network targets')}: ${p.broad_network_targets_allowed?tr('مسموحة','Allowed'):tr('ممنوعة','Blocked')}</div>${table([tr('الأصل الحرج','Critical asset'),tr('دليل الحرجية','Criticality evidence'),tr('العناوين','Addresses'),tr('خطط الإنتاج المعتمدة','Approved production plans')],d.items.map(item=>[item.asset.id?button('asset',h(item.asset.hostname||item.asset.external_id),item.asset.id,'text-button'):h(item.asset.hostname||item.asset.external_id),`${h(item.context.business_service)}<div class="secondary">${h(item.context.service_criticality)} · ${h(item.event_id)}</div>`,`<span class="mono">${item.asset.addresses.map(h).join('<br>')||'—'}</span>`,item.approved_production_plans.map(plan=>`${h(plan.plan_id)} · ${h(plan.tier)}${plan.rate_limit_per_minute?` · ${plan.rate_limit_per_minute}/${tr('دقيقة','min')}`:''}`).join('<br>')||tr('لا توجد','None')]),tr('لا توجد أصول مسجلة كحرجة','No assets are classified as critical'),{total:d.total,limit:d.items.length||1,offset:0})}</div></section>`;}
async function vulnerabilitiesView(){const [base,inventory,assessments,risk,validation,coverage,critical]=await Promise.all([capabilityView(),api('/api/software-vulnerabilities?limit=50'),api('/api/vulnerability-assessments?limit=20'),api('/api/vulnerability-risk?limit=50'),api('/api/validation-program?limit=25'),api('/api/detection-coverage?limit=50'),api('/api/critical-production-protection')]);return base+criticalProductionPanel(critical)+vulnerabilityRiskPanel(risk)+validationProgramPanel(validation)+detectionCoveragePanel(coverage)+vulnerabilityAssessmentPanel(assessments)+softwareVulnerabilityPanel(inventory);}
function identityDirectoriesPanel(d){const iLabel=value=>({'windows-local':tr('حسابات Windows المحلية','Windows local accounts'),'active-directory':'Active Directory',ldap:'LDAP','entra-id':'Microsoft Entra ID','aws-iam':'AWS IAM','azure-rbac':'Azure RBAC','gcp-iam':'Google Cloud IAM','local-api':tr('واجهة محلية','Local API'),'graph-api':'Microsoft Graph','cloud-api':tr('واجهة سحابية','Cloud API'),'export-import':tr('تصدير واستيراد','Export / import'),'membership-added':tr('إضافة عضو','Member added'),'membership-removed':tr('إزالة عضو','Member removed'),'privilege-granted':tr('منح صلاحية','Privilege granted'),'privilege-revoked':tr('سحب صلاحية','Privilege revoked'),'principal-added':tr('حساب جديد','Account added'),'principal-removed':tr('حساب محذوف','Account removed'),'principal-enabled':tr('تفعيل حساب','Account enabled'),'principal-disabled':tr('تعطيل حساب','Account disabled')})[value]||value;return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('تكامل أنظمة الهوية ومراقبة المجموعات والامتيازات','Identity directory integration and group/privilege change monitoring')} · CG-014</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar||d.claim,d.claim))}</div>${table([tr('الدليل والموصل','Directory / connector'),tr('الحسابات والمجموعات','Accounts / groups'),tr('أعضاء المجموعات المميزة','Privileged group members'),tr('التغييرات منذ اللقطة السابقة','Changes since previous snapshot')],d.items.map(item=>[`${h(iLabel(item.directory.type))}<div class="secondary mono">${h(item.directory.ref)}</div><div class="secondary">${h(iLabel(item.connector.method))} · ${tr('قراءة فقط','Read only')}${item.connector.credential_ref?` · ${h(item.connector.credential_ref)}`:''}<br>${h(date(item.observed_at))}</div>`,`${tr('مستخدمون','Users')}: ${item.counts.users} (${item.counts.enabled_users} ${tr('مفعّل','enabled')}) · ${tr('مجموعات','Groups')}: ${item.counts.groups}<div class="secondary">${tr('حسابات مميزة','Privileged principals')}: ${item.counts.privileged_principals} · ${tr('عضويات','Memberships')}: ${item.counts.memberships} · ${tr('صلاحيات','Privileges')}: ${item.counts.privileges}</div>`,item.privileged_members.map(m=>`${h(m.member_ref.replace(/^member:/,''))} → ${h(m.group_ref.replace(/^group:/,''))}`).join('<br>')||'—',`${item.previous_snapshot_at?`${tr('مقارنة مع','Compared with')} ${h(date(item.previous_snapshot_at))}`:tr('أول لقطة لهذا الدليل','First snapshot of this directory')}<div class="secondary">${item.changes.slice(0,20).map(change=>`${h(iLabel(change.type))}${change.privileged?' ⚠':''}: ${h(change.member_ref||change.principal_ref||'')}${change.group_ref?` → ${h(change.group_ref)}`:''}${change.privilege?` · ${h(change.privilege)}`:''}`).join('<br>')||tr('لا تغييرات','No changes')}</div>${button('event',tr('دليل لقطة الهوية','Identity snapshot evidence'),item.event_id,'text-button')}`]),tr('لا توجد لقطات أنظمة هوية','No identity directory snapshots'),d)}</div></section>`;}
function identityThreatsPanel(d){const tLabel=value=>({'mfa-not-registered':tr('حساب بلا MFA','Account without MFA'),'stale-account':tr('حساب راكد','Stale account'),'password-not-rotated':tr('كلمة مرور قديمة','Password not rotated'),'password-spraying':tr('رش كلمات المرور','Password spraying'),'brute-force':tr('تخمين متكرر','Brute force'),'brute-force-then-success':tr('تخمين ثم نجاح','Brute force then success'),'impossible-travel':tr('سفر مستحيل','Impossible travel'),'new-country-signin':tr('دخول من دولة جديدة','New-country sign-in'),'risky-oauth-consent':tr('موافقة OAuth خطرة','Risky OAuth consent'),'broad-oauth-consent':tr('موافقة OAuth واسعة','Broad OAuth consent'),'idp-change-unauthorized':tr('تعديل IdP بلا تفويض','Unauthorized IdP change'),'idp-change-authorized':tr('تعديل IdP مصرح','Authorized IdP change')})[value]||value;const counts=Object.entries(d.by_type).map(([k,v])=>`${h(tLabel(k))}: ${v}`).join(' · ');return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('اكتشاف تهديدات الهوية','Identity threat detection')} · CG-015</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar||d.claim,d.claim))}</div><div class="secondary">${counts||tr('لا نتائج','No findings')}<br>${tr('التغطية','Coverage')}: ${tr('حسابات','accounts')} ${d.coverage.accounts} (MFA ${tr('معروف','known')} ${d.coverage.mfa_known}) · ${tr('عمليات دخول','sign-ins')} ${d.coverage.signins} · OAuth ${d.coverage.consents} · IdP ${d.coverage.idp_changes}</div>${table([tr('النتيجة','Finding'),tr('الموضوع','Subject'),tr('التفاصيل','Detail'),tr('الدليل','Directory / evidence')],d.items.map(f=>[`${h(tLabel(f.type))}<div class="secondary">${pill(f.severity)}</div>`,(({federation:tr('الاتحاد (Federation)','Federation'),'conditional-access':tr('الوصول المشروط','Conditional access'),'mfa-policy':tr('سياسة MFA','MFA policy'),'sso-certificate':tr('شهادة SSO','SSO certificate'),'password-policy':tr('سياسة كلمات المرور','Password policy'),'identity-provider':tr('مزود الهوية','Identity provider'),'token-lifetime':tr('عمر الرمز','Token lifetime'),branding:tr('العلامة','Branding')})[f.subject]?h(({federation:tr('الاتحاد (Federation)','Federation'),'conditional-access':tr('الوصول المشروط','Conditional access'),'mfa-policy':tr('سياسة MFA','MFA policy'),'sso-certificate':tr('شهادة SSO','SSO certificate'),'password-policy':tr('سياسة كلمات المرور','Password policy'),'identity-provider':tr('مزود الهوية','Identity provider'),'token-lifetime':tr('عمر الرمز','Token lifetime'),branding:tr('العلامة','Branding')})[f.subject]):`<span class="mono">${h(f.subject)}</span>`),h(tr(f.detail_ar||f.detail,f.detail)),`<span class="mono">${h(f.directory_ref)}</span><br>${button('event',tr('دليل الهوية','Identity evidence'),f.event_id,'text-button')}`]),tr('لا توجد نتائج تهديدات هوية','No identity threat findings'),d)}</div></section>`;}
function jitPanel(d){const stateLabel=value=>({pending:tr('بانتظار الموافقة','Pending approval'),active:tr('فعّال','Active'),expired:tr('منتهي','Expired'),exhausted:tr('استُنفدت الإجراءات','Action cap reached'),denied:tr('مرفوض','Denied'),revoked:tr('ملغى','Revoked')})[value]||value;const me=state.user||{};return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('صلاحيات مؤقتة عند الحاجة (JIT)','Just-in-time privileges')} · CG-017</h2>${(me.base_role||me.role)!=='admin'?button('jit-request',tr('طلب صلاحية مؤقتة','Request temporary privilege'),'','primary'):''}</div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar||d.claim,d.claim))}</div>${me.jit?`<div class="hint">${tr('دورك الآن','Your role now')}: ${h(me.role)} (${tr('مؤقت حتى','temporary until')} ${h(date(me.jit.expires_at))} · ${tr('إجراءات متبقية','actions left')} ${me.jit.actions_left})</div>`:''}${table([tr('المستخدم والدور','User / role'),tr('النطاق والسبب','Scope / reason'),tr('المدة والحد','Duration / cap'),tr('الحالة','State'),tr('القرار','Decision')],d.items.map(g=>[`${h(g.username)}<div class="secondary">${h(g.base_role)} → ${h(g.requested_role)}</div>`,`${h(g.scope)}<div class="secondary">${h(g.reason)}</div>`,`${g.duration_minutes} ${tr('دقيقة','min')} · ${g.used_actions}/${g.max_actions}<div class="secondary">${g.starts_at?`${h(date(g.starts_at))} → ${h(date(g.expires_at))}`:'—'}</div>`,h(stateLabel(g.state)),`${g.decided_by_name?`${h(g.decided_by_name)} · ${h(date(g.decided_at))}`:'—'}<div class="secondary">${g.state==='pending'&&(me.base_role||me.role)==='admin'&&g.user_id!==me.id?button('jit-approve',tr('موافقة','Approve'),g.id,'small primary')+' '+button('jit-deny',tr('رفض','Deny'),g.id,'small ghost'):''}${['pending','active'].includes(g.state)&&(g.user_id===me.id||(me.base_role||me.role)==='admin')?' '+button('jit-revoke',tr('إلغاء','Revoke'),g.id,'small ghost'):''}</div>`]),tr('لا توجد طلبات صلاحيات مؤقتة','No just-in-time requests'),{total:d.items.length,limit:d.items.length||1,offset:0})}</div></section>`;}
const usersBaseView=usersView;
function mfaPanel(d){return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('المصادقة متعددة العوامل الحديثة','Recent multi-factor authentication')} · CG-034</h2>${!d.enabled?button('mfa-enroll',tr('تفعيل TOTP','Enable TOTP'),'','primary'):!d.recent?button('mfa-verify',tr('تحقق الآن','Verify now'),'','primary'):''}</div><div class="panel-body"><div class="hint">${tr('الإجراءات الحساسة تحتاج رمز TOTP تم التحقق منه خلال آخر خمس دقائق. مادة التسجيل مشفرة بمفتاح محلي ولا تظهر في التدقيق.','Sensitive operations require a TOTP verified within the last five minutes. Enrollment material is encrypted with a local key and never appears in audit.')}</div>${table([tr('الحالة','State'),tr('آخر تحقق','Last verification'),tr('انتهاء الحداثة','Freshness expires')],[[d.enabled?tr('مفعّل','Enabled'):tr('غير مفعّل','Not enabled'),d.verified_at?h(date(d.verified_at)):'—',d.expires_at?h(date(d.expires_at)):'—']],'')}</div></section>`;}
function breakGlassPanel(d){const me=state.user||{},stateLabel=value=>({pending:tr('بانتظار موافقة ثانية','Pending second approval'),active:tr('فعّال','Active'),expired:tr('منتهي','Expired'),exhausted:tr('مستنفد','Exhausted'),denied:tr('مرفوض','Denied'),revoked:tr('ملغى','Revoked')})[value]||value;return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('وصول الطوارئ المضبوط','Controlled break-glass')} · CG-034</h2>${button('break-glass-request',tr('طلب وصول طوارئ','Request emergency access'),'','danger')}</div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar||d.claim,d.claim))}</div>${me.break_glass?`<div class="hint">${tr('وصول الطوارئ فعّال','Emergency access active')}: ${h(me.break_glass.scope)} · ${me.break_glass.actions_left} ${tr('إجراء متبقٍ','actions left')}</div>`:''}${table([tr('المستخدم والنطاق','User / scope'),tr('السبب','Reason'),tr('المدة والحد','Duration / cap'),tr('الحالة','State'),tr('الموافقة','Approval')],d.items.map(g=>[`${h(g.username)}<div class="secondary">${h(g.scope)}</div>`,h(g.reason),`${g.duration_minutes} ${tr('دقيقة','min')} · ${g.used_actions}/${g.max_actions}`,h(stateLabel(g.state)),`${g.approved_by_name?h(g.approved_by_name):'—'}<div class="secondary">${g.state==='pending'&&(me.base_role||me.role)==='admin'&&g.user_id!==me.id?button('break-glass-approve',tr('موافقة','Approve'),g.id,'small primary')+' '+button('break-glass-deny',tr('رفض','Deny'),g.id,'small ghost'):''}${['pending','active'].includes(g.state)&&(g.user_id===me.id||(me.base_role||me.role)==='admin')?' '+button('break-glass-revoke',tr('إلغاء','Revoke'),g.id,'small ghost'):''}</div>`]),tr('لا توجد طلبات طوارئ','No emergency requests'),{total:d.items.length,limit:d.items.length||1,offset:0})}</div></section>`;}
usersView=async()=>{const [jit,me,mfa,breakGlass]=await Promise.all([api('/api/jit'),api('/api/auth/me'),api('/api/auth/mfa'),api('/api/break-glass')]);state.user={...state.user,...me.user};let base='';if((me.user.role)==='admin')base=await usersBaseView();else base=header(tr('الصلاحيات المؤقتة وحماية الحساب.','Temporary privileges and account protection.'));return base+mfaPanel(mfa)+breakGlassPanel(breakGlass)+jitPanel(jit);};
function normalizedLogsPanel(d){const cLabel=value=>({syslog:'Syslog',flow:'NetFlow/IPFIX',ids:'IDS/IPS',dns:'DNS',dhcp:'DHCP',vpn:'VPN',firewall:tr('جدار ناري','Firewall'),waf:'WAF',nac:'NAC',ztna:'ZTNA','cloud-audit':tr('تدقيق سحابي','Cloud audit')})[value]||value;return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('السجلات الموحّدة','Normalised logs')} · CG-018</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar||d.claim,d.claim))}</div><div class="secondary">${Object.entries(d.by_category).map(([k,v])=>`${h(cLabel(k))}: ${v}`).join(' · ')||tr('لا سجلات','No logs')}<br>${d.batches.slice(0,10).map(b=>`${h(b.source_name)} (${h(b.format)}) ${b.record_count}/${b.line_count}${b.rejected_count?` · ${tr('مرفوض','rejected')} ${b.rejected_count}`:''}`).join('<br>')}</div>${table([tr('الوقت والنوع','Time / category'),tr('الإجراء والنتيجة','Action / outcome'),tr('المصدر → الوجهة','Source → destination'),tr('المستخدم والجهاز','User / host'),tr('التفاصيل','Detail')],d.items.map(r=>[`${h(date(r.time))}<div class="secondary">${h(cLabel(r.category))} · ${h(r.format)}</div>`,`${h(r.action||'—')}<div class="secondary">${h(r.outcome||'')}</div>`,`<span class="mono">${h(r.src_ip||'—')}${r.src_port!==null?':'+r.src_port:''} → ${h(r.dst_ip||'—')}${r.dst_port!==null?':'+r.dst_port:''}</span><div class="secondary">${h(r.protocol||'')}${r.bytes!==null?` · ${r.bytes} B`:''}</div>`,`${h(r.user||'—')}<div class="secondary">${h(r.host||'')}${r.mac?` · ${h(r.mac)}`:''}</div>`,`${h(r.signature||r.query||'')}<div class="secondary">${h(r.message||'')}</div>`]),tr('لا توجد سجلات موحّدة','No normalised logs'),d)}</div></section>`;}
async function eventsView(){const [base,logs]=await Promise.all([listView(),api('/api/normalized-logs?limit=50')]);return base+normalizedLogsPanel(logs);}
function networkAnalysisPanel(d){const zLabel=value=>({'internal->internal':tr('داخلي ← داخلي','Internal → internal'),'internal->external':tr('داخلي ← الإنترنت','Internal → Internet'),'external->internal':tr('الإنترنت ← داخلي','Internet → internal'),'external->external':tr('عام ← عام (مثل عنوان IPv6 العام لهذا الجهاز)','Public → public (e.g. this host’s global IPv6)')})[value]||value;const rLabel=value=>({'random-looking-label':tr('اسم عشوائي الشكل','Random-looking label'),'very-long-name':tr('اسم طويل جدًا','Very long name'),'txt-query':tr('استعلام TXT','TXT query'),'null-query':tr('استعلام NULL','NULL query')})[value]||(String(value).startsWith('many-unique-subdomains')?tr('نطاقات فرعية كثيرة: ','Many unique subdomains: ')+value.split(':')[1]:value);return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('تحليل الاتصالات والتعرض وDNS والحركة الجانبية','Connections, exposure, DNS and lateral movement')} · CG-019</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar||d.claim,d.claim))}</div><div class="secondary">${tr('سجلات محللة','Records analysed')}: ${d.records_analysed} · ${Object.entries(d.zones).map(([k,v])=>`${h(zLabel(k))}: ${v}`).join(' · ')||tr('لا اتصالات','No connections')}</div><h3>${tr('مؤشرات الحركة الجانبية','Lateral-movement indicators')}</h3>${table([tr('المصدر','Source'),tr('الأهداف','Targets'),tr('المنافذ','Ports'),tr('الفترة','Window')],d.lateral_movement.map(l=>[`<span class="mono">${h(l.src_ip)}</span> ${pill(l.severity)}`,String(l.targets),h(l.ports.join(', ')),`${h(date(l.first))} → ${h(date(l.last))}`]),tr('لا مؤشرات حركة جانبية','No lateral-movement indicators'),{total:d.lateral_movement.length,limit:d.lateral_movement.length||1,offset:0})}<h3>${tr('التعرض للإنترنت','Internet exposure')}</h3>${table([tr('الجهاز الداخلي','Internal host'),tr('المنفذ والخدمة','Port / service'),tr('مصادر خارجية','External sources'),tr('الخطورة','Severity')],d.exposure.map(x=>[`<span class="mono">${h(x.internal_ip)}</span>`,`${x.port}${x.service?` · ${h(x.service)}`:''}`,String(x.external_sources),pill(x.severity)]),tr('لا تعرض وارد مسموح','No allowed inbound exposure'),{total:d.exposure.length,limit:d.exposure.length||1,offset:0})}<h3>${tr('DNS غير المعتاد','Unusual DNS')}</h3>${table([tr('الاسم','Name'),tr('الأسباب','Reasons'),tr('العميل','Client')],d.unusual_dns.slice(0,50).map(q=>[`<span class="mono">${h(q.query)}</span>`,q.reasons.map(rLabel).map(h).join(tr('، ',', ')),h(q.client_ip||'—')]),tr('لا استعلامات DNS غير معتادة','No unusual DNS'),{total:d.unusual_dns.length,limit:Math.max(1,Math.min(50,d.unusual_dns.length)),offset:0})}<h3>${tr('أكثر الاتصالات','Top connections')}</h3>${table([tr('من ← إلى','From → to'),tr('المنطقة','Zone'),tr('المنافذ','Ports'),tr('الأحداث','Events')],d.connections.slice(0,30).map(c=>[`<span class="mono">${h(c.src_ip)} → ${h(c.dst_ip)}</span>`,h(zLabel(c.zone)),h(c.ports.join(', ')),`${c.events}${c.blocked?` · ${tr('محظور','blocked')} ${c.blocked}`:''}`]),tr('لا اتصالات','No connections'),{total:Math.min(30,d.connections.length),limit:Math.max(1,Math.min(30,d.connections.length)),offset:0})}</div></section>`;}
const networkGapsView=visibilityGapsView;
visibilityGapsView=async()=>{const [base,analysis]=await Promise.all([networkGapsView(),api('/api/network-analysis')]);return base+networkAnalysisPanel(analysis);};
function topologySvg(t){const n=t.nodes.slice(0,40),w=720,hgt=420,cx=w/2,cy=hgt/2,r=Math.min(cx,cy)-60,pos=new Map(n.map((node,i)=>[node.node_id,{x:cx+r*Math.cos(2*Math.PI*i/Math.max(n.length,1)-Math.PI/2),y:cy+r*Math.sin(2*Math.PI*i/Math.max(n.length,1)-Math.PI/2)}]));
  const state=node=>!node.health?'unknown':node.health.reachability==='unreachable'?'down':(node.health.overall_health!==null&&node.health.overall_health<=3)?'warn':'ok';
  const links=t.links.filter(l=>pos.has(l.source)&&pos.has(l.target)).map(l=>{const a=pos.get(l.source),b=pos.get(l.target);return `<line class="topo-link topo-link-${h(l.status)}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"><title>${h(l.source_port||'')} ↔ ${h(l.target_port||'')} · ${h(l.status)}</title></line>`;}).join('');
  const nodes=n.map(node=>{const p=pos.get(node.node_id);return `<g class="topo-node topo-${state(node)}"><circle cx="${p.x}" cy="${p.y}" r="16"></circle><text x="${p.x}" y="${p.y+32}" text-anchor="middle">${h(String(node.label||node.ip||'').slice(0,20))}</text><title>${h(node.label||'')} · ${h(node.device_type)} · ${h(node.ip||'')}${node.health?` · health ${node.health.overall_health??'?'}/10`:''}</title></g>`;}).join('');
  return `<svg class="topology-map" viewBox="0 0 ${w} ${hgt}" role="img" aria-label="${tr('خريطة الطوبولوجيا','Topology map')}">${links}${nodes}</svg>`;}
function networkTopologyPanel(d){const reach=v=>({reachable:tr('متاح','Reachable'),unreachable:tr('غير متاح','Unreachable'),unknown:tr('غير معروف','Unknown')})[v]||v,typeText=v=>({switch:tr('مبدّل','Switch'),router:tr('موجّه','Router'),'access-point':tr('نقطة وصول/متحكم لاسلكي','Access point / WLC'),firewall:tr('جدار ناري','Firewall'),unknown:tr('غير معروف','Unknown')})[v]||v;
  return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('الطوبولوجيا وصحة الأجهزة من المتحكم','Controller topology and device health')} · CG-041</h2></div><div class="panel-body"><div class="hint">${tr('الطوبولوجيا والصحة كما يبلغ عنها المتحكم (Cisco Catalyst Center أو Huawei iMaster NCE-Campus) أو جيران LLDP من الأجهزة. تُعرض العقد والروابط كما وردت مع حالة الرابط وآخر درجة صحة وإتاحة ومعالج وذاكرة لكل جهاز؛ الجهاز غير المتاح أو بصحة 3 من 10 أو أقل يرفع CG-NET-HEALTH-041. لا يُهيأ شيء على الشبكة ولا تُرسم روابط مخمّنة.',d.claim)}</div>
    ${d.items.length?d.items.map(t=>`<div class="secondary">${h(({'cisco-catalyst-center':'Cisco Catalyst Center','huawei-imaster-nce':'Huawei iMaster NCE-Campus','device-lldp':tr('جيران LLDP من الجهاز','Device LLDP neighbours'),'manual-import':tr('استيراد يدوي','Manual import')})[t.source]||t.source)} · ${h(date(t.observed_at))} · ${t.counts.nodes} ${tr('جهاز','devices')} · ${t.counts.links} ${tr('رابط','links')} · ${t.counts.down_links} ${tr('رابط متوقف','links down')}</div>${topologySvg(t)}${table([tr('الجهاز','Device'),tr('النوع','Type'),tr('الصحة','Health'),tr('المعالج / الذاكرة','CPU / memory')],t.nodes.map(n=>[`<strong>${h(n.label||n.node_id)}</strong><div class="secondary mono">${h(n.ip||'')} · ${h(n.platform||'')}</div>`,h(typeText(n.device_type)),n.health?`${n.health.reachability==='unreachable'?`<span class="pill danger">${tr('غير متاح','Unreachable')}</span>`:(n.health.overall_health!==null&&n.health.overall_health<=3)?`<span class="pill warning">${tr('متدهور','Degraded')}</span>`:`<span class="pill success">${tr('سليم','Healthy')}</span>`} ${n.health.overall_health??'—'}/10 · ${h(reach(n.health.reachability))}`:'—',n.health?`${n.health.cpu_percent===null?'—':n.health.cpu_percent+'%'} / ${n.health.memory_percent===null?'—':n.health.memory_percent+'%'}`:'—']),'',{total:t.nodes.length,limit:t.nodes.length,offset:0})}`).join(''):`<div class="secondary">${tr('لم تُستورد طوبولوجيا بعد. شغّل scripts/cisco-connector.js catalyst-topology أو scripts/huawei-connector.js vrp-lldp واستورد الملف.','No topology imported yet. Run scripts/cisco-connector.js catalyst-topology or scripts/huawei-connector.js vrp-lldp and import the file.')}</div>`}</div></section>`;}
