async function aiAnalystView(){const [alerts,policy]=await Promise.all([api('/api/alerts?limit=100'),api('/api/ai-model-policy')]);const modelPanel=`<section class="panel"><div class="panel-head"><h2>${tr('سياسة النماذج','Model policy')} · CG-038</h2></div><div class="panel-body"><div class="detail-grid">${detail(tr('المسار الأساسي','Primary route'),`${pill('unit-tested')} ${h(policy.local.provider)}<div class="secondary">${tr('تبقى البيانات على هذا الجهاز','Data stays on this host')}</div>`)}${detail(tr('Cloud AI الاختيارية','Optional Cloud AI'),`${pill(policy.cloud.enabled?'unit-tested':policy.cloud.connector_available?'not-configured':'unavailable')}<div class="secondary">${tr('تتطلب موصلًا صريحًا وموافقة عميل سارية وMFA حديثة، ولا تسمح إلا بالمخطط المنقح الثابت.','Requires an explicit connector, current customer consent and recent MFA, and permits only the fixed redacted schema.')}</div>`)}</div><div class="hint">${h(policy.claim[state.lang])}</div><div class="secondary">${tr('حقول الخروج المسموحة','Allowed outbound fields')}: <span class="mono">${policy.cloud.allowed_payload_fields.map(h).join(', ')}</span></div><div class="secondary">${tr('الفئات المحظورة','Prohibited classes')}: ${policy.cloud.prohibited_payload_fields.map(h).join(' · ')}</div></div></section><div class="divider"></div>`;return header(tr('شرح محلي قائم على الأدلة: ماذا حدث، لماذا هو مشبوه، الدليل، الثقة، والحل.','Local evidence-grounded explanation: what happened, why suspicious, evidence, confidence and solution.'))+modelPanel+`<div class="hint">${tr('لا يُرسل أي محتوى إلى نموذج خارجي، ولا يحوّل ناتج القاعدة إلى حقيقة مؤكدة. اختر تنبيهًا لعرض الشرح بالعربية أو الإنجليزية حسب لغة الواجهة.','No content is sent to an external model, and a rule outcome is never presented as confirmed fact. Choose an alert to see the explanation in the current Arabic or English interface.')}</div>`+table([tr('التنبيه','Alert'),tr('القاعدة','Rule'),tr('الخطورة','Severity'),tr('الأدلة','Evidence'),tr('الشرح','Analysis')],alerts.items.map(alert=>[h(alertTitle(alert.title)),`<span class="mono">${h(alert.rule_id)} v${h(alert.rule_version)}</span>`,pill(alert.severity),String(alert.evidence_ids.length),button('ai-explain',tr('اشرح التنبيه','Explain alert'),alert.id,'small primary')]),tr('لا توجد تنبيهات لتحليلها','No alerts to analyse'),alerts);}
function ssoSettingsPanel(c){const rows=(c?.role_map||[]).map(m=>[h(m.group),h(({admin:tr('مسؤول','Administrator'),analyst:tr('محلل','Analyst'),viewer:tr('مشاهد','Viewer')})[m.role]||m.role),h(m.tenant),h(m.sites.includes('*')?tr('كل المواقع','All sites'):m.sites.join(tr('، ',', '))),h((m.domains||['*']).map(v=>({cloud:tr('السحابة','Cloud'),network:tr('الشبكة','Network'),identity:tr('الهوية','Identity'),response:tr('الاستجابة','Response'),vulnerability:tr('الثغرات','Vulnerabilities'),'*':tr('كل المجالات','All areas')})[v]||v).join(tr('، ',', ')))]);
  return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('الدخول الموحد OIDC وفصل المستأجر والموقع','OIDC single sign-on and tenant/site scope')} · CG-052</h2></div><div class="panel-body"><div class="hint">${tr('يُقبل رمز الهوية فقط بعد التحقق من التوقيع والمُصدر والجمهور والوقت والـnonce والمستأجر ومطالبة MFA؛ وتمنح كل مجموعة أقل دور لازم ونطاق مواقع محدد. لا يُخزن سر العميل، بل اسم متغير البيئة الذي يحمله.','An ID token is accepted only after its signature, issuer, audience, time, nonce, tenant and MFA claim are verified; each group grants the least role needed and a site scope. The client secret is never stored, only the name of the environment variable holding it.')}</div>
    ${c?`<div class="secondary" dir="ltr">${h(c.issuer)} · ${h(c.client_id)}${c.tenant?` · tenant ${h(c.tenant)}`:''} · MFA: ${h([...c.mfa_amr,...c.mfa_acr].join(', '))}</div>${table([tr('المجموعة','Group'),tr('الدور','Role'),tr('المستأجر','Tenant'),tr('المواقع','Sites'),tr('المجالات','Domains')],rows,'',{total:rows.length,limit:rows.length,offset:0})}`:`<div class="secondary">${tr('الدخول الموحد غير مهيأ.','Single sign-on is not configured.')}</div>`}
    <form data-form="sso-config" class="form-grid"><label>${tr('رابط المُصدر (HTTPS)','Issuer URL (HTTPS)')}<input name="issuer" required dir="ltr" value="${h(c?.issuer||'')}"></label><label>${tr('معرف العميل','Client ID')}<input name="client_id" required dir="ltr" value="${h(c?.client_id||'')}"></label><label>${tr('اسم متغير بيئة سر العميل (اختياري)','Client secret environment variable name (optional)')}<input name="client_secret_env" dir="ltr" value="${h(c?.client_secret_env||'')}"></label><label>${tr('المستأجر المسموح (مطالبة tid)','Allowed tenant (tid claim)')}<input name="tenant" dir="ltr" value="${h(c?.tenant||'')}"></label>
    <label>${tr('ربط المجموعات: سطر لكل مجموعة بالشكل group,role,tenant,site1|site2','Group mapping: one line per group as group,role,tenant,site1|site2')}<textarea name="role_map" rows="4" dir="ltr" required>${h((c?.role_map||[]).map(m=>[m.group,m.role,m.tenant,m.sites.join('|')].join(',')).join('\n'))}</textarea></label><button class="primary" type="submit">${tr('حفظ إعداد SSO (يتطلب MFA حديثًا)','Save SSO settings (recent MFA required)')}</button></form>
  </div></section>`;}
