async function render(){if(!state.user)return;const generation=++state.generation;try{const kind=viewKind();const html=state.user.scope?.restricted?(state.view==='overview'?await scopedOverviewView():['threats','incidents','events','assets','remote'].includes(state.view)?await listView():state.view==='settings'?await usersView():`<section class="panel"><div class="panel-body"><div class="hint">${tr('هذه الواجهة تجمع كل المواقع، ونطاقك مقصور على مواقع محددة.','This view aggregates every site; your access is limited to specific sites.')}</div></div></section>`):kind==='overview'?await overview():kind==='discovery'?await discoveryView():kind==='sources'?await sourcesView():kind==='settings'?await usersView():state.view==='network-map'?await visibilityGapsView():state.view==='policies'?await securityOutcomesView():state.view==='reports'?await riskRegisterView():state.view==='threats'?await threatsView():state.view==='incidents'?await incidentsView():state.view==='ai-analyst'?await aiAnalystView():state.view==='events'?await eventsView():state.view==='identity'?await identityAuditView():state.view==='vulnerabilities'?await vulnerabilitiesView():state.view==='response'?await responseView():state.view==='cloud'?await cloudView():capabilityCatalog[state.view]?await capabilityView():await listView();if(generation===state.generation&&state.user){shell(html);if(['sources','discovery'].includes(kind)&&state.user.role==='admin'){const b=document.createElement('button');b.type='button';b.dataset.action='local-inventory';b.className='small ghost';b.textContent=tr('جرد هذا الجهاز','Inventory this host');document.querySelector('.heading-actions').append(b);}}}catch(e){toast(e.message,true);}}
