  if(action==='ai-explain'){const a=await api(`/api/ai-analysis/${id}`),lang=state.lang,steps=a.solution[lang],claimRefs=claimIds=>`<div class="secondary mono">${tr('المصادر','Sources')}: ${claimIds.flatMap(claimId=>a.grounding.claims.find(claim=>claim.id===claimId)?.source_ids||[]).map(h).join(' · ')}</div>`;modal(tr('شرح محلل الأدلة المحلي','Local evidence analyst explanation'),`<div class="hint">${h(a.limitations[lang])}</div><div class="detail-grid">${detail(tr('ماذا حدث؟','What happened?'),h(a.what_happened[lang])+claimRefs(a.what_happened.claim_ids))}${detail(tr('لماذا هو مشبوه؟','Why suspicious?'),h(a.why_suspicious[lang])+claimRefs(a.why_suspicious.claim_ids))}${detail(tr('مستوى الثقة','Confidence'),`${pill(a.confidence.level)} ${a.confidence.score}/100<br><span class="secondary">${h(a.confidence.basis[lang])}</span>${claimRefs(a.confidence.claim_ids)}`)}${detail(tr('الحل','Solution'),`<ol>${steps.map(step=>`<li>${h(step)}</li>`).join('')}</ol><span class="mono">${h(a.solution.playbook_id)}</span>${claimRefs(a.solution.claim_ids)}`)}</div><section class="detail-section"><h3>${tr('الدليل','Evidence')}</h3>${a.evidence.map(item=>`<div class="list-row"><div><span class="mono">${h(item.kind)}</span><div class="secondary">${h(date(item.observed_at))} · SHA-256 ${h(item.sanitized_sha256)}</div></div>${button('event',tr('فتح','Open'),item.event_id,'text-button')}</div>`).join('')||`<p>${tr('لا توجد مراجع دليل متاحة؛ الثقة منخفضة.','No evidence reference is available; confidence is low.')}</p>`}</section><section class="detail-section"><h3>${tr('إجراءات مقترحة من الكتالوج','Catalog actions the analyst may propose')} · CG-039</h3><div class="hint">${tr('اقتراحات محددة النوع فقط؛ لا ينفذ شيء قبل قرار إنسان وموافقة مستقلة.','Typed proposals only; nothing runs before a human decision and independent approval.')}</div>${(a.proposed_actions||[]).map(s=>`<div class="list-row"><div><strong>${h(aiActionText(s.action_type))}</strong> <span class="mono">${aiTarget(s.target)}</span><div class="secondary">${h(lang==='ar'?s.rationale_ar:s.rationale_en)}</div></div>${button('ai-propose',tr('اقترح على إنسان','Propose to a human'),`${id}|${s.suggestion_id}`,'text-button')}</div>`).join('')||`<p class="secondary">${tr('لا يوجد إجراء من الكتالوج تدعمه أدلة هذا التنبيه.','No catalog action is supported by this alert evidence.')}</p>`}</section><section class="detail-section"><h3>${tr('مصادر الادعاءات','Claim sources')} · CG-037</h3><div class="hint">${h(a.grounding.withheld[lang])}</div>${a.grounding.sources.map(source=>`<div class="list-row"><div><strong>${h(source.type)}</strong> · ${h(source.label)}<div class="secondary mono">${h(source.id)} · ${h(source.route)}${source.sha256?` · SHA-256 ${h(source.sha256)}`:''}</div></div></div>`).join('')}</section><p class="form-note">${tr('كل الادعاءات مسندة','All claims grounded')}: ${h(String(a.grounding.all_claims_grounded))} · ${tr('منع الادعاءات غير المسندة','Unsupported claims rejected')}: ${h(String(a.grounding.unsupported_claims_rejected))} · ${tr('الوضع','Mode')}: ${h(a.mode)} · ${tr('استُخدم AI خارجي','External AI used')}: ${h(String(a.external_ai_used))}</p>`);return;}
  if(action==='new-user'){modal(tr('إضافة مستخدم محلي','Create local user'),`<form data-form="user"><div class="form-grid"><label>${tr('اسم المستخدم','Username')}<input name="username" pattern="[A-Za-z0-9_.\\-]{3,64}" maxlength="64" required autocomplete="off"></label><label>${tr('الدور','Role')}<select name="role"><option value="viewer">${tr('مشاهد','Viewer')}</option><option value="analyst">${tr('محلل','Analyst')}</option><option value="admin">${tr('مسؤول','Administrator')}</option></select></label><label class="full">${tr('كلمة مرور — 14 حرفًا على الأقل','Password — at least 14 characters')}<input name="password" type="password" minlength="14" maxlength="256" required autocomplete="new-password"></label></div><div id="form-error" role="alert" hidden></div><div class="form-actions"><button class="primary">${tr('إنشاء الحساب','Create account')}</button></div></form>`);return;}
  if(action==='new-temporary-permit'){const assets=await api('/api/assets?limit=100');modal(tr('طلب تصريح مؤقت محدد النطاق','Request scoped temporary permit'),assets.items.length?`<div class="hint">${tr('جميع حقول النطاق إلزامية. لا تُقبل any أو الشبكات العامة، ويجب أن يعتمد الطلب مسؤول آخر.','Every scope field is required. Any/global networks are rejected, and another administrator must approve.')}</div><form data-form="temporary-permit"><div class="form-grid"><label>${tr('الجهاز','Device')}<select name="asset_id">${assets.items.map(a=>`<option value="${h(a.id)}">${h(a.hostname||a.external_id)}</option>`).join('')}</select></label><label>${tr('المستخدم','User ref')}<input name="user_ref" required></label><label>${tr('المصدر','Source ref')}<input name="source_ref" required></label><label>${tr('الوجهة','Destination ref')}<input name="destination_ref" required></label><label>${tr('البروتوكول','Protocol')}<select name="protocol"><option value="tcp">TCP</option><option value="udp">UDP</option></select></label><label>${tr('المنفذ','Port')}<input name="port" type="number" min="1" max="65535" required></label><label>${tr('المدة بالدقائق','Duration in minutes')}<input name="duration_minutes" type="number" min="1" max="1440" value="60" required></label><label>${tr('المالك','Owner ref')}<input name="owner_ref" required></label><label class="full">${tr('السبب','Reason')}<textarea name="reason" maxlength="1000" required></textarea></label></div><div id="form-error" role="alert" hidden></div><div class="form-actions"><button class="primary">${tr('إرسال للموافقة','Submit for approval')}</button></div></form>`:`<div class="hint">${tr('أضف جهازًا مركزيًا أولًا.','Add a central device first.')}</div>`);return;}
  if(['approve-temporary-permit','revoke-temporary-permit'].includes(action)){await api(`/api/temporary-permits/${id}/${action.startsWith('approve')?'approve':'revoke'}`,{});toast(tr('تم تحديث التصريح المؤقت.','Temporary permit updated.'));await render();return;}
  if(action==='new-response-action'){const [asset,catalog]=await Promise.all([api(`/api/assets/${id}`),api('/api/response-actions')]),options=catalog.items.flatMap(item=>item.connectors.filter(c=>c.target_asset_refs.includes(asset.external_id)).map(c=>`<option value="${h(item.id)}|${h(c.connector_id)}">${h(item.id)} · ${h(c.connector_id)}</option>`));modal(tr('معاينة إجراء استجابة typed','Preview typed response action'),options.length?`<div class="hint">${tr('اختر الإجراء والموصل ثم املأ حقول الهدف الخاصة به فقط. تُرفض الحقول والأوامر غير المعروفة. يحتاج الطلب مرجع تفويض وموافقة مسؤول آخر، ولا يعد ناجحًا حتى يرجع الموصل دليل الحالة اللاحقة.','Choose an action and connector, then fill only its target fields. Unknown fields and raw commands are rejected. An authorization reference and another administrator are required, and success needs connector postcondition evidence.')}</div><form data-form="response-action" data-id="${id}"><div class="form-grid"><label class="full">${tr('الإجراء والموصل','Action / connector')}<select name="action_connector" required>${options.join('')}</select></label><label>IP<input name="ip" value="${h(asset.addresses[0]||'')}"></label><label>${tr('البروتوكول','Protocol')}<select name="protocol"><option value="tcp">TCP</option><option value="udp">UDP</option></select></label><label>${tr('المنفذ','Port')}<input name="port" type="number" min="1" max="65535"></label><label>${tr('الاتجاه','Direction')}<select name="direction"><option value="both">both</option><option value="inbound">inbound</option><option value="outbound">outbound</option></select></label><label>${tr('مرجع التطبيق','Application ref')}<input name="application_ref"></label><label>${tr('النطاق','Domain')}<input name="domain"></label><label>${tr('مرجع الخدمة','Service ref')}<input name="service_ref"></label><label>${tr('الإعداد الدائم المطلوب','Desired permanent configuration ref')}<input name="desired_configuration_ref"></label><label>${tr('طريقة الاسترداد','Recovery method')}<select name="recovery_method"><option value="reinstall">reinstall</option><option value="restore-configuration">restore-configuration</option><option value="rollback-package">rollback-package</option><option value="restore-snapshot">restore-snapshot</option></select></label><label>${tr('أثر الاسترداد','Recovery artifact ref')}<input name="recovery_artifact_ref"></label><label>${tr('مالك الاسترداد','Recovery owner ref')}<input name="recovery_owner_ref"></label><label class="full">${tr('خطوات الاسترداد — سطر لكل خطوة','Recovery steps — one per line')}<textarea name="recovery_steps"></textarea></label><label class="full">${tr('خطوات تحقق الاسترداد — سطر لكل خطوة','Recovery verification — one per line')}<textarea name="recovery_verification_steps"></textarea></label><label>${tr('مرجع الملف','File ref')}<input name="file_ref"></label><label>SHA-256<input name="sha256" maxlength="64"></label><label>${tr('مرجع الجهاز','Device ref')}<input name="device_ref" value="${h(asset.external_id)}"></label><label>${tr('واجهة السويتش','Switch interface')}<input name="interface_ref"></label><label>${tr('دليل منفذ edge','Edge-port provenance')}<input name="provenance_ref"></label><label>${tr('مرجع التفويض','Authorization ref')}<input name="authorization_ref" required></label><label>${tr('الصلاحية (ثانية)','Validity (seconds)')}<input name="ttl_seconds" type="number" min="60" max="3600" value="600" required></label><label class="full">${tr('السبب والأثر','Reason / impact')}<textarea name="reason" maxlength="1000" required></textarea></label></div><div id="form-error" role="alert" hidden></div><div class="form-actions"><button class="primary">${tr('إنشاء المعاينة','Create preview')}</button></div></form>`:`<div class="hint">${tr('لا يوجد موصل مختبر يعلن قدرة استجابة لهذا الأصل. أضف دليل response.capability من مصدر الموصل أولًا.','No tested connector advertises a response capability for this asset. Ingest response.capability evidence from the connector source first.')}</div>`);return;}
  if(action==='new-action'){modal(tr('معاينة تغيير أهمية الأصل','Preview asset criticality change'),`<div class="hint">${tr('تغيير محلي في سجل الأصل؛ لا إجراء على الجهاز. يحتاج موافقة مسؤول آخر.','A local record change, not a device action. A second administrator must approve.')}</div><form data-form="action" data-id="${id}"><div class="form-grid"><label>${tr('الأهمية الجديدة','New criticality')}<select name="criticality">${['standard','important','critical'].map(x=>`<option value="${x}">${h(label(x))}</option>`).join('')}</select></label><label>${tr('الصلاحية (ثانية)','Validity (seconds)')}<input type="number" name="ttl_seconds" min="60" max="3600" value="600" required></label><label class="full">${tr('السبب وتقدير الأثر','Reason and impact')}<textarea name="reason" maxlength="1000" required></textarea></label></div><div id="form-error" role="alert" hidden></div><div class="form-actions"><button class="primary">${tr('إنشاء المعاينة','Create preview')}</button></div></form>`);return;}
